\encoding UTF8
\copy (WITH vp AS (SELECT * FROM question_bank WHERE pipeline_metadata::jsonb ? 'verified_provisional' AND quality_review_status IN ('human_verified','auto_judged_high') AND NOT (pipeline_metadata::jsonb ? 'demoted_at') AND NOT (pipeline_metadata::jsonb ? 'ai_extras' AND (pipeline_metadata::jsonb->'ai_extras') ? 'topic_match_quality' AND ((pipeline_metadata::jsonb->'ai_extras')->>'topic_match_quality')='fallback') AND (pipeline_metadata::jsonb ? 'match_tier' AND (pipeline_metadata::jsonb->>'match_tier') IN ('tier1_page_inline','tier1b_position_page_inline')) AND id NOT IN (SELECT id FROM gate2c_demoted)), r AS (SELECT *, row_number() OVER (PARTITION BY exam_type, subject_area ORDER BY md5(id::text)) AS rn FROM vp) SELECT json_build_object('id',id,'subj',subject_area,'exam',exam_type,'q',question_text,'a',option_a,'b',option_b,'c',option_c,'d',option_d,'e',option_e,'key',correct_answer) FROM r WHERE (exam_type='AYT' AND subject_area IN ('KIMYA','FIZIK','BIYOLOJI') AND rn<=10) OR (exam_type='TYT' AND subject_area IN ('KIMYA','FIZIK','BIYOLOJI') AND rn<=5) OR (subject_area IN ('TARIH','EDEBIYAT','TURKCE','MATEMATIK','GEOMETRI') AND rn<=3) ORDER BY md5(id::text)) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_wave1/tier1_validate.jsonl'
